use verus::prelude::*;

fn solve(n: i8, s: Vec<char>) -> i8 {
    // s must have length exactly n ≥ 0
    requires! {
        n >= 0,
        (n as usize) == s.len()
    }
    // the result (number of region‐changes) lies between 0 and n
    ensures! { |transitions: i8| 0 <= transitions && transitions <= n }

    // x and y track our current position
    let mut x: i8 = 0;
    let mut y: i8 = 0;
    // prev_region: None if we haven't entered any region yet,
    // Some(true) if last region was A (x>y),
    // Some(false) if last region was B (y>x).
    let mut prev_region: Option<bool> = None;
    // count of transitions
    let mut transitions: i8 = 0;

    // Index i will count how many moves we've processed so far.
    let mut i: usize = 0;
    while i < s.len() {
        // Loop invariants
        invariant! { i <= s.len() }
        // x and y are non‐negative, and sum to the number of moves processed
        invariant! { 0 <= x && 0 <= y }
        invariant! { x + y == i as i8 }
        // transitions so far is between 0 and i
        invariant! { 0 <= transitions && transitions <= i as i8 }
        decreases! { s.len() - i }

        let mv = s[i];
        i += 1;

        // apply the move
        match mv {
            'R' => x += 1,
            'U' => y += 1,
            _ => {} // input guaranteed to be only 'R' or 'U'
        }

        // if on the border x==y, skip checking regions
        if x == y {
            continue;
        }

        // determine current region: true for A (x>y), false for B (y>x)
        let current_region = x > y;

        match prev_region {
            None => {
                // first time entering a region: record it, no transition counted
                prev_region = Some(current_region);
            }
            Some(prev) => {
                // if we changed region, count a transition
                if prev != current_region {
                    transitions += 1;
                    prev_region = Some(current_region);
                }
            }
        }
    }

    transitions
}

